// implementContext renders the "Component context" section of the user
// message from the scaffold record the create just wrote: which template
// and version the component came from, the role its block kind plays in
// the integration, and the values it was rendered with. The record is
// also in the file dump, but buried; surfacing it as labeled facts is
// what lets the model wire messages in the right direction rather than
// guess. A missing or unreadable record degrades to the template name
// alone — the implement must not fail on context it can approximate.
func implementContext(dir, templateName string) string {
	var b strings.Builder
	b.WriteString("Component context:\n")
	fmt.Fprintf(&b, "- scaffolded from template %q", templateName)

	rec, err := template.LoadScaffold(filepath.Join(dir, template.ScaffoldRelPath))
	if err != nil {
		b.WriteString("\n")
		return b.String()
	}
	if rec.Version != "" {
		fmt.Fprintf(&b, " (version %s)", rec.Version)
	}
	b.WriteString("\n")
	if rec.BlockKind != "" {
		fmt.Fprintf(&b, "- block kind: %s%s\n", rec.BlockKind, blockKindNote(rec))
	}
	if rec.Role != "" {
		fmt.Fprintf(&b, "- template role: %s\n", rec.Role)
	}
	// Map keys marshal in sorted order, so the line is deterministic and
	// a cached prefix stays cached when only later sections change.
	if len(rec.Values) > 0 {
		if data, err := json.Marshal(rec.Values); err == nil {
			fmt.Fprintf(&b, "- rendered with values: %s\n", data)
		}
	}
	return b.String()
}

// blockKindNote glosses a block kind with what it means for the code the
// model is about to write: the message direction the component wires and
// which side the external system sits on.
func blockKindNote(rec *template.Scaffold) string {
	var parts []string
	switch template.MessageDirection(rec.BlockKind) {
	case template.MessageDirectionPublish:
		parts = append(parts, "publishes messages")
	case template.MessageDirectionSubscribe:
		parts = append(parts, "subscribes to messages")
	case template.MessageDirectionNone:
		if rec.BlockKind == template.BlockKindTransactional {
			parts = append(parts, "talks with the external system directly, wires no messages")
		}
	}
	switch rec.DataFlow {
	case "in":
		parts = append(parts, "flows data in from the external system")
	case "out":
		parts = append(parts, "flows data out to the external system")
	}
	if len(parts) == 0 {
		return ""
	}
	return " (" + strings.Join(parts, "; ") + ")"
}

