// complete dispatches to the streaming or one-shot completion.
func (c *Client) complete(ctx context.Context, messages []Message, onDelta func(string)) (string, error) {
	if onDelta != nil {
		return c.CompleteStream(ctx, messages, onDelta)
	}
	return c.Complete(ctx, messages)
}

// parseFiles extracts the file set from the model's reply. The strict
// shape is the whole reply as one JSON object, but code models reliably
// deviate in a few known ways — a markdown fence, a reasoning block,
// leading prose — so the reply is tried under each tolerance in turn.
func parseFiles(reply string) ([]File, error) {
	var parsed struct {
		Files []File `json:"files"`
	}
	parsedOK := false
	for _, candidate := range replyCandidates(reply) {
		if err := json.Unmarshal([]byte(candidate), &parsed); err == nil {
			parsedOK = true
			break
		}
	}
	if !parsedOK {
		return nil, fmt.Errorf("berget reply is not the expected JSON file set (reply begins %q)\ntry a different --model, or make the prompt more specific", snippet(reply))
	}
	if len(parsed.Files) == 0 {
		return nil, fmt.Errorf("berget reply lists no files\nmake the prompt more specific about what the component should do")
	}
	for _, f := range parsed.Files {
		if !filepath.IsLocal(f.Path) {
			return nil, fmt.Errorf("berget reply names %q, which escapes the component directory\nre-run the command; if it persists, the model is not following the output contract", f.Path)
		}
	}
	return parsed.Files, nil
}

// replyCandidates yields the reply under each tolerance, most strict
// first: verbatim, unwrapped from a code fence, past a reasoning block,
// and finally the span between the outermost braces, which is where the
// JSON sits when the model frames it in prose.
func replyCandidates(reply string) []string {
	text := strings.TrimSpace(reply)
	candidates := []string{text}

	fenced := text
	if strings.HasPrefix(fenced, "```") {
		if i := strings.Index(fenced, "\n"); i >= 0 {
			fenced = fenced[i+1:]
		}
		fenced = strings.TrimSpace(strings.TrimSuffix(strings.TrimSpace(fenced), "```"))
		candidates = append(candidates, fenced)
	}

	// Reasoning models emit a think block before the answer; the answer
	// is what follows it.
	if i := strings.LastIndex(text, "</think>"); i >= 0 {
		text = strings.TrimSpace(text[i+len("</think>"):])
		candidates = append(candidates, text)
	}

	if start := strings.Index(text, "{"); start >= 0 {
		if end := strings.LastIndex(text, "}"); end > start {
			candidates = append(candidates, text[start:end+1])
		}
	}
	return candidates
}

// snippet quotes the head of a reply for an error message, so a contract
// failure shows what the model actually said instead of a bare parse
// error.
func snippet(reply string) string {
	text := strings.TrimSpace(reply)
	const max = 80
	if len(text) > max {
		text = text[:max] + "…"
	}
	return text
}

